package com.obysoft.faithOS.service;
import java.io.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import com.obysoft.faithOS.dto.*;import com.obysoft.faithOS.entity.*;import com.obysoft.faithOS.exception.ResourceNotFoundException;import com.obysoft.faithOS.repository.*;
@Service public class MemberMessageService{private final MemberMessageRepository repo;private final UserRepository users;private final CurrentChurchService current;private final SensitiveDataService sensitive;private final int retentionDays;public MemberMessageService(MemberMessageRepository r,UserRepository u,CurrentChurchService c,SensitiveDataService s,@org.springframework.beans.factory.annotation.Value("${app.retention.message-days:730}")int days){repo=r;users=u;current=c;sensitive=s;retentionDays=days;}
 @Transactional(readOnly=true)public List<MessageContactResponse> contacts(){User me=current.user();boolean staff=staff(me);return users.findAllByChurchIdAndActiveTrueOrderByFirstNameAsc(me.getChurch().getId()).stream().filter(u->!u.getId().equals(me.getId())&&(staff||staff(u))).map(u->new MessageContactResponse(u.getId(),u.getFirstName()+" "+u.getLastName(),u.getEmail(),u.getRole())).toList();}
 @Transactional public List<MemberMessageResponse> conversation(Long otherId){User me=current.user(),other=other(otherId,me);if(!staff(me)&&!staff(other))throw new IllegalArgumentException("Members may communicate with church staff.");List<MemberMessage> values=repo.conversation(me.getChurch().getId(),me.getId(),otherId);values.stream().filter(m->m.getRecipient().getId().equals(me.getId())&&m.getReadAt()==null).forEach(m->m.setReadAt(LocalDateTime.now()));return values.stream().map(this::response).toList();}
 @Transactional public MemberMessageResponse send(Long otherId,String text,MultipartFile file){User me=current.user(),other=other(otherId,me);if(!staff(me)&&!staff(other))throw new IllegalArgumentException("Members may communicate with church staff.");if((text==null||text.isBlank())&&(file==null||file.isEmpty()))throw new IllegalArgumentException("Write a message or attach a file.");MemberMessage m=new MemberMessage();m.setChurch(me.getChurch());m.setSender(me);m.setRecipient(other);m.setMessage(sensitive.encrypt(text==null||text.isBlank()?"Attachment":text.trim()));m.setExpiresAt(LocalDateTime.now().plusDays(retentionDays));if(file!=null&&!file.isEmpty()){if(file.getSize()>10*1024*1024)throw new IllegalArgumentException("Attachment must be 10 MB or smaller.");try{byte[] data=file.getBytes();String type=safeType(data,file.getContentType());m.setAttachmentName(safe(file.getOriginalFilename()));m.setAttachmentType(type);m.setAttachmentSize(file.getSize());m.setAttachmentData(sensitive.encrypt(data));}catch(IOException e){throw new IllegalStateException("Unable to read attachment.",e);}}return response(repo.save(m));}
 @Transactional(readOnly=true)public Attachment attachment(Long id){User me=current.user();MemberMessage m=repo.findByIdAndChurchId(id,me.getChurch().getId()).filter(v->v.getSender().getId().equals(me.getId())||v.getRecipient().getId().equals(me.getId())).filter(v->v.getAttachmentData()!=null).orElseThrow(()->new ResourceNotFoundException("Attachment not found."));return new Attachment(sensitive.decrypt(m.getAttachmentData()),m.getAttachmentName(),"application/octet-stream");}
 private User other(Long id,User me){return users.findByIdAndChurchId(id,me.getChurch().getId()).orElseThrow(()->new ResourceNotFoundException("Church member not found."));}private boolean staff(User u){return u.getRole()!=Role.MEMBER;}private String safe(String n){if(n==null||n.isBlank())return"attachment";n=n.replace('\\','/');n=n.substring(n.lastIndexOf('/')+1);return n.substring(0,Math.min(255,n.length()));}private String safeType(byte[] d,String declared){if(d.length>=4&&d[0]==0x25&&d[1]==0x50&&d[2]==0x44&&d[3]==0x46)return"application/pdf";if(d.length>=8&&d[0]==(byte)0x89&&d[1]==0x50&&d[2]==0x4e&&d[3]==0x47)return"image/png";if(d.length>=3&&d[0]==(byte)0xff&&d[1]==(byte)0xd8&&d[2]==(byte)0xff)return"image/jpeg";if("text/plain".equalsIgnoreCase(declared)&&isText(d))return"text/plain";throw new IllegalArgumentException("Only verified PDF, PNG, JPEG, and plain-text attachments are allowed.");}private boolean isText(byte[] d){for(byte b:d)if(b==0)return false;try{java.nio.charset.StandardCharsets.UTF_8.newDecoder().decode(java.nio.ByteBuffer.wrap(d));return true;}catch(java.nio.charset.CharacterCodingException e){return false;}}private MemberMessageResponse response(MemberMessage m){User s=m.getSender();return new MemberMessageResponse(m.getId(),s.getId(),s.getFirstName()+" "+s.getLastName(),m.getRecipient().getId(),sensitive.decrypt(m.getMessage()),m.getAttachmentName(),m.getAttachmentType(),m.getAttachmentSize(),m.getCreatedAt(),m.getReadAt());}public record Attachment(byte[] data,String name,String type){}}
